/**
 * Libertas OS API is intended to be used by
 * Libertas application developers.
 *
 * Libertas OS is running on top of Libertas Hub.
 * End-users create tasks as instances of applications.
 *
 * The API comprises the major components below:
 * - Device access API
 * - Time and timers
 * - Persistent database
 * - Messaging
 * - Miscellanies
*/

/**
 * A timer object.
 *
 * @see {@link libertasTimerNewInterval}
 * @see {@link libertasTimerNewDeadline}
 * @see {@link libertasTimerUpdate}
 * @see {@link libertasTimerCancel}
 *
 */
declare class LibertasTimer {
}

/** Platform identity: positive signed-64 range; zero only for defined system contexts.
 * Keep IDs as bigint, including collection keys. Never convert through number.
 */
declare type LibertasId = bigint;
/** Opaque peer route handle, retained unchanged for responses and signaling. */
declare type LibertasPeer = LibertasId;

/**
 * A logical device endpoint.
 *
 * @see {@link libertasDeviceReadReq}
 * @see {@link libertasDeviceWriteReq}
 * @see {@link libertasDeviceCommandReq}
 * @see {@link libertasAppSubscribeReq}
 * @see {@link libertasSetOnDevice}
 */
declare type LibertasDevice = LibertasId;

/**
 * A WiFi or Ethernet device.
 *
 * @see {@link libertasNetConnectDevice}
 *
 */
declare type LibertasLanDevice = LibertasId;

/**
 * A virtual device. The behaviors of the device are managed by application code.
 *
 * Virtual devices interact with the user during the runtime of Libertas App tasks.
 *
 * @see [Virtual Device API](/doc/developers_doc/virtual_device_api/)
 * @see {@link libertasVirtualDeviceCommandRsp}
 * @see {@link libertasVirtualDeviceWriteRsp}
 * @see {@link libertasVirtualDeviceUpdateEvents}
 * @see {@link libertasVirtualDeviceAttributesChanged}
 * @see {@link libertasVirtualDeviceAttributesRsp}
 * @see {@link libertasSetOnVirtualDevice}
 */
declare type LibertasVirtualDevice = LibertasId;

/**
 * The Date and Time data type. Usually seconds from Unix epoch time. Note the time is always in UTC, but it is presented to the end-user in local time on the UI.
 */
declare type LibertasDateTime = number;
/**
 * The 24-hour time data type, usually with seconds precision.
 */
declare type LibertasTimeOnly = number;
/**
 * User data type. Base type is an integer of a user ID or user group ID.
 * User fields and arrays do not implicitly select the current user. Declare
 * an explicit schema Default when an initial identity is intended.
 *
 * @see {@link libertasMessageText}
 */
declare type LibertasUser = LibertasId;
/**
 * Transaction identifier carried by every Libertas interaction.
 *
 * A transaction ID is never optional at the runtime boundary. Libertas does
 * not reserve a value to mean "missing" or "ignored"; each interaction
 * protocol is responsible for designating and documenting such a value when
 * needed.
 */
declare type LibertasTransId = number;

/**
 * Specialized virtual device for endpoint interactions.
 * Data schema must be predefined and published by the server developer.
 *
 * @remarks In App source, `@LibertasExcludeUI` may mark an
 * `@LibertasEndpointServer` field carrying a resolved protocol schema or a
 * reachable protocol `Request`/`SubscriptionRequest` variant. Hub Control
 * omits the marked server Endpoint from its UI-device list, while generated
 * Control UI omits the marked operation; admin workflows use the complete
 * schema. Every server
 * Endpoint sharing one resolved `ProtocolSchema` root must use the same marker
 * value. The marker does not change the Endpoint protocol, routing,
 * authorization, runtime behavior, or wire representation.
 */
declare type LibertasEndpoint = LibertasVirtualDevice;

/**
 * A handle to an indexed database table.
 */
declare type LibertasDataStore = number;

/**
 * This action code is passed to the device and virtual device callback functions.
 *
 * Based on the Matter interaction action code. Libertas added the {@link DeviceAction.ReadResponse} code to complete the logic.
 *
 * @see {@link LibertasDeviceCallback}
 * @see {@link LibertasVirtualDeviceCallback}
 *
 */
declare type DeviceAction = number;

/**
 * Represents an App's access permissions to a cluster of a {@link LibertasDevice}.
 *
 * @see {@link LibertasDeviceClusterAccess}
 * @see {@link libertasDeviceGetClusterAccess}
 */
declare type AppAccess = number;

/**
 * Used with Matter events.
 */
declare type MatterPriority = number;

/**
 * Used with Matter events.
 */
declare type MatterTimestampType = number;

/**
 * Libertas Hub status values returned to Matter clients in bits 16-31 of a
 * 32-bit status. Matter virtual devices must not return these values.
 */
declare const LibertasMatterHubStatus: Readonly<{
    /**
     * A queued command was replaced, or a retained attribute write differs
     * from the value finally written. Replaced commands receive this rejection
     * after the surviving interaction completes, even for identical commands.
     * Only the surviving command receives its own success or error. Write results
     * compare each requested value with the value finally written by the pooled
     * interaction, with real write errors taking precedence.
     */
    Superseded: 0x00010000;
}>;

/**
 * A value of the Matter data model, which Libertas adopts.
 * The value can be the value of an attribute or a field of a command or event.
 * Note that a command or event must be a LibertasStruct, which could be empty.
 *
 * @see {@link LibertasStruct}
 */
declare type LibertasValue = number | boolean | string | BigInt | Uint8Array | LibertasValue[] | LibertasStruct | null | undefined;

/**
 * A LibertasStruct can be a LibertasValue. A command or event must be a LibertasStruct, which could be empty.
 *
 * @see {@link LibertasValue}
 * @see {@link LibertasCommand}
 * @see {@link LibertasEvent}
 */
declare type LibertasStruct = Map<number, LibertasValue>;

/**
 * A collection of attributes within a cluster as attribute id/value pairs.
 *
 * @see {@link LibertasClusterAttributes}
 * @see {@link LibertasClusterReport}
 */
declare type LibertasAttributes = Map<number, LibertasValue>;

/**
 * A map of ID/status code pairs. The ID can be an attribute ID, command ID, or event ID.
 * Each status is an unsigned 32-bit Libertas Matter client status. Bits 0-7
 * contain the interaction-model status, bits 8-15 contain the optional cluster
 * status, and bits 16-31 contain a {@link LibertasMatterHubStatus}.
 *
 * @see {@link LibertasClusterWriteRsp}
 * @see {@link LibertasClusterReport}
 */
declare type LibertasIdStatus = Map<number, number>;

/**
 * A map of cluster ID and a {@link AppAccess}.
 *
 * @see {@link libertasDeviceGetClusterAccess}
 */
declare type LibertasDeviceClusterAccess = Map<number, number>;

/**
 * A tuple representing a Matter event.
 *
 * @see {@link LibertasClusterReport}
 * @see {@link libertasVirtualDeviceUpdateEvents}
 */
declare type LibertasEvent = [cluster: number, eventNo: number, priority: MatterPriority, timestamp: number, timestampType: MatterTimestampType, eventId: number, eventData?: LibertasStruct];

/**
 * A map of event IDs and "urgent" flags.
 *
 * @remarks Use {@link libertasMakeIterable} to use LibertasClusterEventSubscription in a "for...of" loop.
 *
 */
declare type LibertasClusterEventSubscription = Map<number, boolean>;

/**
 * A tuple representing a Matter command.
 *
 * @see {@link LibertasCommandRsp}
 * @see {@link LibertasVirtualDeviceReq}
 * @see {@link libertasSetOnDevice}
 * @see {@link libertasDeviceCommandReq}
 * @see {@link libertasVirtualDeviceCommandRsp}
 */
declare type LibertasCommand = [cluster: number, id: number, data?: LibertasStruct];

/**
 * A tuple representing a collection of attributes (id/value pairs) of a cluster.
 */
declare type LibertasClusterAttributes = [cluster: number, attributes: LibertasAttributes];

/**
 * A tuple representing a read request from a Libertas App task.
 *
 * @see {@link LibertasVirtualDeviceReq}
 * @see {@link libertasDeviceReadReq}
 * @see {@link libertasVirtualDeviceAttributesChanged}
 *
 * @remarks
 * The subscribe request is slightly different than {@link LibertasClusterSubscribeReq} in that an event id can be set as "urgent" in subscription.
 *
 * We currently do not support read by array index. We think it is a bad design. We may add that support in the future if there is a real need.
 */
declare type LibertasClusterReadReq = [cluster: number, attributes: number[], events?: number[] ];

/**
 * Represents a cluster subscription request of a device.
 *
 * @see {@link LibertasClusterEventSubscription}
 * @see {@link LibertasDeviceSubscribeReq}
 * @see {@link libertasAppSubscribeReq}
 * @see {@link libertasSetOnDevice}
 *
 * @remarks
 * The subscribe request is different than {@link LibertasClusterReadReq} in that an event ID can be set as "urgent."
 * The minInterval and maxInterval are in seconds.
 *
 * The effective minInterval and maxInterval may differ due to the varying requirements of multiple agents and device settings.
 *
 * The maxInterval affects the report timeout. The underlying Libertas OS performs timeout detection. The Libertas App task can keep idling until a report or error occurs.
 */
declare type LibertasClusterSubscribeReq = [cluster: number, minInterval: number, maxInterval: number, attributes: number[], events?: LibertasClusterEventSubscription ];

/**
 * Represents a subscription request for a logical device. `eventMin` is required if an event subscription is included.
 *
 * @see {@link LibertasDevice}
 * @see {@link LibertasClusterSubscribeReq}
 * @see {@link libertasAppSubscribeReq}
 *
 * @remarks We currently do not support subscribe by array index. We think it is a bad design. We may add that support in the future if there is a real need.
 */
declare type LibertasDeviceSubscribeReq = [device: LibertasDevice, clusterSubRequests: LibertasClusterSubscribeReq[], eventMin?: number ];

/**
 * A command response. The response may be a status code or a command, depending on the data model's design.
 * If an error occurs, the response will include the error status code. Applications may use runtime type checking to
 * find out the type of the response.
 * A numeric client response is an unsigned 32-bit Libertas Matter status. See
 * {@link LibertasMatterHubStatus}. A virtual device may return only a standard
 * Matter status in bits 0-15.
 *
 * @see {@link LibertasCommand}
 * @see {@link libertasDeviceCommandReq}
 * @see {@link libertasVirtualDeviceCommandRsp}
 */
declare type LibertasCommandRsp = number | LibertasCommand;

/**
 * Represents a "write response." The key is cluster.
 *
 * @remarks The original write request may be split into multiple requests to the destination. In that case, multiple "write responses" will be received.
 */
declare type LibertasClusterWriteRsp = Map<number, LibertasIdStatus>;

/**
 * Represents cluster report data, part of a device or virtual device report.
 *
 * @see {@link LibertasAttributes}
 * @see {@link LibertasIdStatus}
 * @see {@link LibertasEvent}
 * @see {@link LibertasDeviceRsp}
 * @see {@link libertasDeviceReadReq}
 * @see {@link libertasVirtualDeviceAttributesRsp}
 *
 * @remarks attributeStatus must contain the status code of every requested ID. Status code 0 represents a success; otherwise, it is an error. If a status code 0 is present on an ID but the ID is not in the attributes table, a "null" value shall be assumed (this is important for the Lua VM because Lua cannot have a nil value in a table).
 *
 * A virtual device's failure to include all IDs in the attribute status will result in unknown behavior.
 */
declare type LibertasClusterReport = [cluster: number, attributes: LibertasAttributes, attributeStatus: LibertasIdStatus, events?: LibertasEvent[], eventStatus?: LibertasIdStatus];

/**
 * A request to a virtual device. It can be one of three types, depending on the context.
 *
 * @see {@link LibertasClusterReadReq}
 * @see {@link LibertasClusterAttributes}
 * @see {@link LibertasCommand}
 * @see {@link LibertasVirtualDeviceCallback}
 * @see {@link libertasSetOnVirtualDevice}
 */
declare type LibertasVirtualDeviceReq = LibertasClusterReadReq[] | LibertasClusterAttributes[] | LibertasCommand;

/**
 * All possible responses. A numeric status response uses the Libertas Matter
 * client-status encoding documented by {@link LibertasCommandRsp}.
 *
 * @see {@link LibertasCommandRsp}
 * @see {@link LibertasClusterWriteRsp}
 * @see {@link LibertasClusterReport}
 * @see {@link LibertasDeviceCallback}
 * @see {@link libertasSetOnDevice}
 */
declare type LibertasDeviceRsp = LibertasCommandRsp | LibertasClusterWriteRsp[] | LibertasClusterReport[] | number;

/**
 * The signature of a device callback function.
 *
 * @param device A {@link LibertasDevice}.
 * @param action The {@link DeviceAction}. Note Libertas added a {@link DeviceAction.ReadResponse} action.
 * @param data The response data. It's a union type. The value shall be cast to a type decided by action.
 * @param tag The arbitrary data passed to {@link libertasSetOnDevice} with the callback instance.
 * @param transId The transaction ID. Matter designates 0 as ignored for unsolicited reports.
 *
 * @see {@link LibertasDeviceRsp}
 * @see {@link libertasSetOnDevice}
 *
 * @remarks For a "status response," a nonzero transId refers to a request;
 * Matter's ignored value 0 indicates device status instead. Subscription
 * reports carry the same ignored value when no request is being correlated.
 */
declare type LibertasDeviceCallback = (device: LibertasDevice, action: DeviceAction, data: LibertasDeviceRsp, tag: any | undefined, transId: LibertasTransId) => void;

/**
 * Possible interactions of an endpoint connection.
 */
declare type EndpointAction = number;

/**
 * The signature of a virtual device I/O callback function.
 *
 * @param device A {@link LibertasVirtualDevice}.
 * @param peer Uniquely identifies a peer as subscription ID. See remarks.
 * @param transId The transaction ID of the original request. See remarks.
 * @param action The {@link DeviceAction}. See remarks
 * @param data The request data. It's a union type. The value shall be cast to a type decided by action.
 * @param tag The arbitrary data passed to {@link libertasSetOnVirtualDevice} with the callback instance.
 *
 * @see {@link libertasSetOnVirtualDevice}
 *
 * @remarks The callback is used to notify the virtual device of a request. Each request has an internally assigned transaction ID (transId) by the engine.
 * The transId must be passed back in the corresponding response.
 *
 * Valid actions:
 * {@link DeviceAction.ReadRequest}, {@link DeviceAction.SubscribeRequest}, and {@link DeviceAction.ReportData} all request attribute data. {@link DeviceAction.ReadRequest}
 * is a one-time read. {@link DeviceAction.SubscribeRequest} is an initial subscribe request. {@link DeviceAction.ReportData} is for
 * continuous subscription data report. Combined with `peer`, the Libertas App can keep track of current subscribers. The Libertas App can also keep the last subscription related request time to
 * calculate interval duration for more flexible subscrption delivery. A virtual device may even respond more data than requested if the common dirty-marking algorithm is not adequate.
 */

declare type LibertasVirtualDeviceCallback = (device: LibertasVirtualDevice, peer: LibertasPeer, transId: LibertasTransId, action: DeviceAction, data: LibertasVirtualDeviceReq, tag?: any) => void;

/**
 * Callback of an endpoint connection.
 *
 * @param device A LibertasEndpoint client or server.
 * @param action interaction action.
 * @param peer On a server callback, an opaque endpoint-peer handle to retain
 * and pass back unchanged. On a client callback for server-originated traffic,
 * the configured serving endpoint.
 * @param tag The arbitrary data passed to {@link libertasSetOnEndpoint} with the callback instance.
 * @param data The protocol message, or undefined for the standardized endpoint
 * signals `PeerUp`, `PeerDown`, `PeerAlive`, and `PeerTimeout`. Applications
 * must branch on `action` before decoding or forwarding data to consumers.
 * @param transId The opaque transaction ID. The endpoint protocol designates 0
 * as ignored for unsolicited traffic. A server passes a nonzero request value
 * back unchanged instead of interpreting or embedding it in protocol data.
 *
 * @remarks
 * ## Normative endpoint subscription and signaling contract
 *
 * This is the complete closed-loop contract for endpoint subscriptions, peer
 * handles, reports, and standardized endpoint signals, and is the sole ground
 * truth for the behavior exposed to TypeScript Apps. Manuals, samples, tests,
 * and implementation notes are non-normative derived material; if they differ,
 * this SDK contract wins. Endpoint application data and endpoint signaling
 * share the callback, but signaling is defined by Libertas and is outside the
 * endpoint's application schema. Applications MUST branch on `action` before
 * decoding or forwarding `data`.
 *
 * Subscription establishment and peer handles:
 *
 * - Every `SubscriptionRequest` MUST pass through the Libertas host. When the
 *   host routes the request, it records the pair `(serving endpoint, opaque
 *   peer handle)` in its in-memory subscription map. That map belongs only to
 *   the current host process: it is never persisted to a database or disk and
 *   is never restored. A host restart clears every pair. There is no direct
 *   client-to-server subscription path that bypasses this record.
 * - The first declared `SubscriptionRequest` whose effective payload is `Nil`
 *   is the default Control subscription. Each new tracking admission obtains
 *   a fresh complete snapshot from the App; the host does not cache payloads.
 *   Apps must answer repeated requests with current complete data as well.
 *   The default stream may be shared, but each watcher is independently
 *   authorized against the default variant's effective `AccessPrivilege`.
 *   Apps must treat peer handles as opaque regardless of stream sharing.
 * - Compatible SubscriptionData updates are an App choice. The App owns their
 *   ordering and consistency; the host only routes them and never merges them.
 * - Every explicit non-default Control subscription, including a later `Nil`
 *   variant, uses the authenticated real client object as its host route. It is
 *   neither cached nor shared. The Control connection owns its lifetime, and
 *   the host closes that client's endpoint relationship when the connection
 *   closes. A transient session ID is never an endpoint peer identity. These
 *   identities remain opaque to the server App despite their host meaning.
 * - The server App MUST start or renew its application subscription state only
 *   after it receives the corresponding `SubscriptionRequest` callback for the
 *   current server incarnation. After host restart, only a fresh host-routed
 *   `SubscriptionRequest` recreates the pair. After server App restart within
 *   the same host uptime, the retained pair is inactive for the new server
 *   incarnation until a fresh host-routed `SubscriptionRequest` reactivates it
 *   and reaches the server callback. A configured relationship, previous
 *   incarnation, or retained pair alone is never an instruction to produce a
 *   stream.
 * - Immediately before invoking the registered server App callback for that
 *   `SubscriptionRequest`, the serving runtime emits a private delivery
 *   acknowledgement to the host. The host activates the pair for the current
 *   server incarnation only after validating that acknowledgement. This
 *   pre-callback boundary permits the callback to synchronously emit
 *   `ReportData` or `PeerAlive`: runtime-to-host FIFO ordering ensures the host
 *   observes the activation acknowledgement first. The acknowledgement is
 *   runtime-private; the App neither receives nor sends it.
 * - If no server endpoint callback is registered, or validation fails before
 *   callback dispatch, the runtime emits a private negative completion instead
 *   of a positive acknowledgement. It retires only that exact pending SUB and
 *   its correlation; another pending SUB or an already-active stream is not
 *   revoked. In particular, a same-`transId` renewal leaves the established
 *   subscription correlation usable until the renewal reaches its positive
 *   callback boundary; a negative renewal removes only its new private
 *   correlation. A positive renewal atomically supersedes the established
 *   same-`transId` correlation. Such a renewal is allowed at the normal
 *   concurrent-subscription limit because it replaces rather than adds an
 *   established stream. A correlated invalid-message response, when
 *   applicable, is put on the runtime FIFO before the negative completion. A
 *   route with no other active or pending SUB is removed. Thus an undispatched
 *   request never grants `ReportData` or `PeerAlive` authority.
 * - A server-side `peer` is only an opaque handle issued by the host. It may
 *   represent anything and may numerically resemble an App, task, endpoint, or
 *   other object ID. The server MUST retain it and pass it back unchanged. It
 *   MUST NOT interpret, transform, manufacture, enumerate, or derive identity
 *   or authorization from the number.
 * - On a client callback for server-originated responses, reports, or signals,
 *   `device` and `peer` identify the client's configured serving endpoint.
 *   Libertas never exposes the endpoint's owning App or task identity.
 *
 * Data and liveness routing:
 *
 * - `ReportData` and `PeerAlive` with no `peer` are broadcast operations. The
 *   host may expand them only through pairs in the serving endpoint's current
 *   in-memory map that a host-routed `SubscriptionRequest` activated for the
 *   current server incarnation; the server cannot supply or infer a client
 *   roster.
 * - Targeted `ReportData` and `PeerAlive` are allowed only when the exact
 *   `(serving endpoint, opaque peer handle)` pair is currently recorded and
 *   active for that server incarnation. A targeted operation does not create,
 *   restore, or reactivate a subscription record.
 * - Attempting targeted `ReportData` or `PeerAlive` for an unrecorded pair is a
 *   protocol and authorization violation by a rogue server. The host reports
 *   the violation and terminates the offending App; it MUST NOT route the
 *   message.
 * - Responses are not subscription fan-out. They are authorized separately by
 *   the host's outstanding-request correlation. A server MUST return the exact
 *   `peer` handle and nonzero `transId` received with that request. A response
 *   neither creates nor requires a subscription-map entry and MUST NOT be used
 *   to publish subscription data.
 *
 * Peer-down removal closes the server side of the loop:
 *
 * - When the host has confirmed a recorded peer down, it delivers `PeerDown`
 *   to the serving App while the pair remains recorded and authorized. The
 *   serving runtime emits a private delivery acknowledgement only after the
 *   registered server callback returns normally. Until the host validates that
 *   post-callback acknowledgement, it retains the pair and retries the
 *   applicable `PeerDown` delivery.
 *   Once callback entry is armed, later client-observation changes or duplicate
 *   Down requests cannot replace that close generation or invalidate its
 *   eventual post-callback acknowledgement.
 * - Merely queuing a later SUB does not cancel an older Down. A positive
 *   pre-callback acknowledgement supersedes that Down only if it has not yet
 *   entered the server callback. If the Down callback has already begun, its
 *   post-callback acknowledgement first closes the old pair while preserving
 *   the later SUB's private token and response correlation; that SUB's later
 *   positive acknowledgement then reactivates the pair. A negative or absent
 *   SUB completion never cancels the Down. Observation revision advanced by
 *   that later request does not stale the older Down while its private SUB
 *   boundary is unresolved; on negative completion the host resumes that
 *   exact Down against the current observation.
 * - The host completes the Down path by removing the exact subscription pair
 *   only after validating that private acknowledgement. It is a runtime-private
 *   protocol message; the App neither receives nor sends it, and there is no
 *   public SDK acknowledgement. After removal, neither broadcast nor targeted
 *   `ReportData` or `PeerAlive` may reach that route; targeting the removed
 *   handle is the rogue-server violation described above. A host restart
 *   instead discards the entire volatile map and does not restore either the
 *   pair or historical pending Down work.
 * - A public remove issued inside the `PeerDown` callback cannot bypass this
 *   boundary: it is redundant until the runtime's post-callback acknowledgement
 *   completes the removal. Before a Down has entered the callback, an explicit
 *   server remove closes the active pair immediately and cancels that pending
 *   Down, while preserving any separately pending later SUB boundary. If an
 *   opaque route becomes unresolvable, the host uses the ordered Down/removal
 *   path instead of silently retaining it.
 * - A fresh `SubscriptionRequest` does not erase a `PeerDown` that already
 *   reached the server callback. The host first completes that Down after its
 *   post-callback acknowledgement while preserving the later request's private
 *   delivery token; only the later request's positive pre-callback
 *   acknowledgement may reactivate the pair. If that later request cannot be
 *   dispatched, the pair remains removed. The host also suppresses Down retries
 *   behind that unresolved later request so the server cannot observe a stale
 *   Down after the new subscription callback.
 * - The server never receives client `PeerUp` and MUST NOT infer a complete
 *   peer roster. A later client interaction begins with a new host-routed
 *   request and whatever opaque handle the host supplies.
 *
 * `PeerAlive` is application-originated but Libertas-standardized signaling:
 *
 * - Only the App serving the endpoint may emit it, on the cadence chosen by
 *   its application protocol. Its wire body is exactly empty: there is no
 *   endpoint status-envelope byte and no application-schema value. Its
 *   transaction ID is the protocol's ignored value, `0`.
 * - When liveness is needed without changed application data, the server MUST
 *   use `PeerAlive`. It MUST NOT fabricate a schema-level "no change"
 *   `ReportData` value or resend unchanged application data solely as a
 *   liveness signal; decoders, caches, observers, and GUIs correctly treat
 *   every `ReportData` message as application data.
 * - It is an observational signal for the current server incarnation only.
 *   The host fences stale incarnation work. On an active subscription, receipt
 *   rearms only the applicable application-owned liveness watchdog and then
 *   returns.
 * - It MUST NOT enter a schema decoder, update or replace cached data, notify a
 *   data observer, render or refresh a GUI, advance a sequence/cursor, or cause
 *   resubscription. It is not a schema-level "no change" payload.
 * - It proves only recent emission by the current server incarnation. It does
 *   not prove that data is unchanged or synchronized, that an earlier response
 *   or report was delivered, or that no data was lost. Protocols needing loss
 *   detection MUST carry sequence, revision, cursor, snapshot, or equivalent
 *   recovery information in real application data.
 * - It is not the inverse of authoritative `PeerDown` and MUST NOT resurrect a
 *   Down peer or stream. Only a delivered `PeerUp` changes that lifecycle
 *   state; the client then resubscribes and rebuilds server-process protocol
 *   state, even if it did not observe a preceding Down.
 *
 * Server lifecycle and host-process boundaries:
 *
 * - Within one host uptime, a recorded pair may survive a server App process
 *   Down/Up cycle so the host can notify the client. It is not active for the
 *   replacement server incarnation. Server `PeerDown` suspends the client's
 *   subscription retry and watchdog work until `PeerUp`; every delivered Up
 *   requires one fresh `SubscriptionRequest`. Only after the host routes that
 *   request and the replacement server receives its callback may the server
 *   recreate application state and emit Data or Alive.
 * - A host restart is different: the process-memory subscription map and
 *   pending lifecycle work are gone, not persisted or restored. Restarted
 *   clients MUST send a fresh `SubscriptionRequest`; routing that request
 *   creates the new pair before the new server callback starts the stream.
 * - `PeerTimeout` is only a local application inference from missing expected
 *   traffic; Libertas infrastructure never emits it. Infrastructure suppresses
 *   obsolete lifecycle work before invoking the callback within the applicable
 *   host uptime, but application data, responses, reports, and `PeerAlive`
 *   remain unreliable and need any recovery required by their protocol.
 */
declare type LibertasEndpointCallback<T> = (device: LibertasEndpoint, action: EndpointAction, peer: LibertasPeer, tag: any, data: T | undefined, transId: LibertasTransId) => void;

/**
 * Set a callback function to receive responses and reports to a device.
 *
 * @param device A {@link LibertasDevice}.
 * @param func The callback function.
 * @param tag A developer-defined value that will be passed to the callback function.
 *
 * @see {@link LibertasDeviceCallback}
 * @see {@link libertasDeviceReadReq}
 * @see {@link libertasDeviceWriteReq}
 * @see {@link libertasDeviceCommandReq}
 * @see {@link libertasAppSubscribeReq}
 */
declare function libertasSetOnDevice(device: LibertasDevice, func: LibertasDeviceCallback, tag?: any): void;

/**
 * Obtain the cluster-access map of a device. This API is used to get basic information about a device.
 * A LibertasDevice may support multiple types of devices with varying capabilities (clusters). This API returns
 * the device's actual supported clusters and their App access rights.
 *
 * Cluster access data is part of the App's static data and is returned without querying the "Descriptor" cluster from the device.
 *
 * @param device A {@link LibertasDevice}.
 * @returns A {@link LibertasDeviceClusterAccess}.
 *
 */
declare function libertasDeviceGetClusterAccess(device: LibertasDevice) : LibertasDeviceClusterAccess;

/**
 * Send an asynchronous read request to the device.
 *
 * @param device A {@link LibertasDevice}.
 * @param requests An array of {@link LibertasClusterReadReq} representing attributes and events for specified clusters.
 * @param eventMin Must present if events are requested.
 * @returns A reference number passed back in {@link LibertasDeviceRsp} of {@link LibertasDeviceCallback} callback.
 *
 * @see {@link libertasDeviceGetClusterAccess}
 * @see {@link LibertasClusterReadReq}
 * @see {@link libertasSetOnDevice}
 *
 * @remarks
 * Use {@link libertasSetOnDevice} to set up the callback function. The callback shall be called later with ReadRsp.
 *
 * The callback will be triggered asynchronously with a {@link LibertasClusterReport}[] array and the reference number.
 *
 * IMPORTANT! The read request may be responded to with more than one response. Multiple read requests may be pooled into one single response.
 *
 */
declare function libertasDeviceReadReq(device: LibertasDevice, requests: LibertasClusterReadReq[], eventMin?: number) : LibertasTransId;

/**
 * Send an asynchronous write request to the device.
 *
 * @param device A {@link LibertasDevice}.
 * @param requests An array of {@link LibertasClusterAttributes}.
 * @returns The reference number of this request.
 *
 * @see {@link libertasDeviceGetClusterAccess}
 * @see {@link LibertasClusterAttributes}
 * @see {@link LibertasClusterWriteRsp}
 * @see {@link libertasSetOnDevice}
 *
 * @remarks
 * Use {@link libertasSetOnDevice} to set up the callback function for the response.
 *
 * The callback will be triggered asynchronously with a {@link LibertasClusterWriteRsp}[] array and the reference number.
 *
 * IMPORTANT! If the task sends another WriteReq before the previous WriteReq is responded to, the previous one may be discarded by Libertas OS.
 * As a general rule, a task shall always wait for the response to the previous interaction before sending another one or only expect the
 * response to the latest request.
 *
 * The request may never reach the recipient if, for example, there is a network problem. In that case, a
 * {@link DeviceAction.StatusResponse} with a {@link Matter.Status.Timeout} will be received from the callback registered with
 * {@link libertasSetOnDevice}.
 *
 * The Libertas App task shall not assume that it is the only process that sends requests. Other agents
 * may also send requests. A task can only receive {@link LibertasClusterWriteRsp} to its written requests.
 *
 * To receive all changes to an attribute, use {@link libertasAppSubscribeReq}.
 *
 */
declare function libertasDeviceWriteReq(device: LibertasDevice, requests: LibertasClusterAttributes[]) : LibertasTransId;

/**
 * Send an asynchronous command request to the device.
 *
 * @param device A {@link LibertasDevice}.
 * @param request The {@link LibertasCommand}.
 * @returns The reference number of this request.
 *
 * @see {@link libertasDeviceGetClusterAccess}
 * @see {@link LibertasCommandRsp}
 * @see {@link libertasSetOnDevice}
 *
 * @remarks
 * Use {@link libertasSetOnDevice} to set up the callback function for the response.
 *
 * The callback will be triggered asynchronously with a {@link LibertasCommandRsp} and the reference number.
 *
 * Pending commands are last-command-wins per logical-device endpoint and
 * cluster to reduce device traffic, including requests from different Apps.
 * Only the newest request/reference per source is retained for completion.
 * A newer surviving request replaces that source's older displaced reference,
 * so the older request receives no separate response.
 * A burst from one peer keeps only its newest queued command; older queued
 * references are discarded without acknowledgement. Commands already sent
 * remain owned by their active interaction.
 * A retained displaced caller always receives LibertasMatterHubStatus.Superseded,
 * only after the surviving interaction completes. Only the surviving command
 * receives its own success or error result. Identical command data does not
 * turn a displaced request into a successful execution.
 * Wait for the previous response before issuing another command when every
 * action matters, and handle rejection because other callers may replace it.
 *
 * The surviving request may never reach the recipient if, for example, there is
 * a network problem. Its caller receives a terminal error such as
 * {@link Matter.Status.Timeout} through the callback registered with
 * {@link libertasSetOnDevice}.
 *
 * The Libertas App task shall not assume that it is the only process that sends requests. Other agents
 * may also send requests. A task can only receive the {@link LibertasCommandRsp} to its command requests.
 *
 * To receive all changes to an attribute, use {@link libertasAppSubscribeReq}.
 */
declare function libertasDeviceCommandReq(device: LibertasDevice, request: LibertasCommand) : LibertasTransId;

/**
 * Replace this App task's complete Matter device subscription list.
 *
 * @param requests An array of {@link LibertasDeviceSubscribeReq}.
 *
 * @see {@link libertasDeviceGetClusterAccess}
 * @see {@link LibertasDeviceSubscribeReq}
 * @see {@link LibertasClusterReport}
 * @see {@link LibertasDeviceRsp}
 * @see {@link libertasSetOnDevice}
 *
 * @remarks
 * Each update is sent in one shot for this task: collect all desired device
 * subscriptions and submit them together. A later accepted list completely
 * replaces this task's previous list; omitted devices and paths are removed.
 * The list may be replaced repeatedly during the task's lifetime. Submitting
 * one device at a time does not add to the earlier list. An empty list clears
 * this task's device subscriptions.
 *
 * Because the Libertas App shares subscriptions with the host and possibly other Libertas Apps, the following behaviors may be observed:
 *
 * 1. The first few data reports may be in response to ReadRequest.
 * 2. The data reports may contain attributes and events that are not subscribed to by this Libertas App.
 * 3. Libertas-OS will handle errors, including timeout. A StatusResponse report will be generated in case of errors.
 *
 * The report data will be passed to the callback function {@link LibertasDeviceCallback} registered with {@link libertasSetOnDevice}.
 */
declare function libertasAppSubscribeReq(requests: LibertasDeviceSubscribeReq[]) : void;

/**
 * Notify the Libertas Libertas App engine that some attributes have changed values.
 * @param device A {@link LibertasVirtualDevice}.
 * @param attributes The list of cluster attribute IDs. We reuse the {@link LibertasClusterReadReq} structure to hold the required data.
 * Note that the event field is always undefined because Libertas OS handles the event reports.
 * @param peer The subscription ID, which can be inferred from the peer in earlier {@link LibertasVirtualDeviceCallback}. Usually it should be undefined, unless
 * the Libertas App needs to manage data report for each individual subscriber.
 *
 * @remarks The Libertas App engine is responsible for reporting each subscription based on the subscribed attributes, events, and minimum/maximum intervals.
 * Even if the virtual device reported the changes, the report may not be generated immediately if the minimum interval has not been reached.
 * Also, when the Libertas Libertas App engine decides to generate a report, it will send a {@link DeviceAction.ReadRequest} or
 * {@link DeviceAction.SubscribeRequest} with an array of {@link LibertasClusterReadReq} for the up-to-date values of the specified
 * attributes and expect a response from {@link libertasVirtualDeviceAttributesRsp} call. If this value is defined, the notification will
 * only be delivered to a single subscriber.
 */
declare function libertasVirtualDeviceAttributesChanged(device: LibertasVirtualDevice, attributes: LibertasClusterReadReq[], peer?: LibertasPeer) : void;

/**
 * Update new events.
 * @param device A {@link LibertasVirtualDevice}.
 * @param events An array of {@link LibertasEvent}.
 *
 * @remarks Libertas OS manages the event reporting. The eventNo field shall be set to 0 and will be ignored. Libertas OS will automatically assign a consecutive number.
 */
declare function libertasVirtualDeviceUpdateEvents(device: LibertasVirtualDevice, events: LibertasEvent[]) : void;

/**
 * Update attributes unsolicited, or in response to a ReadRequest or SubscribeRequest.
 * @param device A {@link LibertasVirtualDevice}.
 * @param peer The peer taskId.
 * @param transId The transaction ID of the request. Matter designates 0 as
 * ignored when this is an unsolicited subscription report.
 * @param attributes An array of {@link LibertasClusterReport}. Note that the events and eventStatus are undefined. Use {@link libertasVirtualDeviceUpdateEvents} to write events.
 *
 * @remarks
 * The framework will maintain a cache of all attributes.
 *
 * A nonzero transId sends a read response or report for the referenced request
 * immediately. Matter's ignored value 0 lets the Libertas OS engine decide when
 * to send subscription reports.
 */
declare function libertasVirtualDeviceAttributesRsp(device: LibertasVirtualDevice, peer: LibertasPeer, transId: LibertasTransId, attributes: LibertasClusterReport[]) : void;

/**
 * Send out command responses.
 * @param device A {@link LibertasVirtualDevice}.
 * @param peer The peer taskId.
 * @param transId The transaction Id of the request.
 * @param rsp A {@link LibertasCommandRsp}. A numeric response must contain only
 * a standard Matter status in bits 0-15; Hub status values are client results
 * and cannot be issued by a virtual device.
 */
declare function libertasVirtualDeviceCommandRsp(device: LibertasVirtualDevice, peer: LibertasPeer, transId: LibertasTransId, rsp: LibertasCommandRsp) : void;

/**
 * Send out write response.
 * @param device A {@link LibertasVirtualDevice}.
 * @param peer The peer taskId.
 * @param transId The transaction Id of the request.
 * @param responses An array of {@link LibertasClusterWriteRsp}. Every numeric
 * status must contain only a standard Matter status in bits 0-15.
 */
declare function libertasVirtualDeviceWriteRsp(device: LibertasVirtualDevice, peer: LibertasPeer, transId: LibertasTransId, responses: LibertasClusterWriteRsp[]) : void;

/**
 * Send out an error status code against an incoming request.
 * @param device A {@link LibertasVirtualDevice}.
 * @param peer The peer taskId.
 * @param transId The transaction Id of the request.
 * @param status A standard Matter StatusIB packed into bits 0-15 as
 * `(clusterStatus << 8) | status`. Omit the cluster status by passing a
 * {@link Matter.Status} value directly. A virtual device must not return a
 * {@link LibertasMatterHubStatus}; those statuses are generated by the Hub for
 * Matter clients only. The runtime rejects nonzero bits 16-31.
 */
declare function libertasVirtualDeviceStatusRsp(device: LibertasVirtualDevice, peer: LibertasPeer, transId: LibertasTransId, status: number) : void;

/**
 * Listen to a virtual device events.
 * @param device A {@link LibertasVirtualDevice}.
 * @param func A {@link LibertasVirtualDeviceCallback} function.
 * @param tag Developer defined data that will be passed to callback function.
 */
declare function libertasSetOnVirtualDevice(device: LibertasVirtualDevice, func: LibertasVirtualDeviceCallback, tag?: any): void;

/**
 * Sends a request or subscribeRequest message to an endpoint.
 *
 * @param device The target {@link LibertasEndpoint}.
 * @param action The interaction action, such as {@link EndpointAction.Request} or {@link EndpointAction.SubscriptionRequest}.
 * @param message The message payload to send.
 *
 * @returns A transaction ID that can be used to track the request and match it with a future response.
 * @remarks A protocol Request may declare
 * `@LibertasAccessPrivilege("Read")`, `"Write"`, or `"Read,Write"` to limit
 * invocation to users with any listed access level on the owning endpoint.
 * Omission means `Read,Write`, because the platform cannot infer the semantic
 * effect of an application request. This per-operation end-user restriction is
 * distinct from whole-task `Permissions`. Runtime clients should hide or
 * disable disallowed requests; the Hub remains authoritative and validates the
 * decoded Request before routing it.
 * @remarks A `Request` or `SubscriptionRequest` variant carrying
 * `@LibertasExcludeUI` remains a valid protocol payload but is not offered by
 * generated Control UI.
 * @remarks A `SubscriptionRequest` participates in the normative endpoint
 * subscription and signaling contract documented on
 * {@link LibertasEndpointCallback}; in particular, every subscription request
 * is routed and recorded by the host before server processing.
 */
declare function libertasEndpointSendRequest<T>(device: LibertasEndpoint, action: EndpointAction, message: T): LibertasTransId;

/**
 * Sends a response to an endpoint for a previously received request.
 *
 * @param device The target {@link LibertasEndpoint}.
 * @param action {@link EndpointAction.Response}, or {@link EndpointAction.EditRequest}
 * to open a complete Request payload for editing without automatic submission.
 * @param message The message payload containing the response data.
 * @param dest The opaque peer handle received with the request. Pass it back
 * unchanged; do not interpret it as an App, task, or object identity.
 * @param transId The opaque transaction ID (ref) from the original request;
 * pass it back unchanged.
 * @remarks Use {@link libertasEndpointReport} for subscription data instead of
 * addressing the broadcast peer through this response API. Response
 * correlation, opaque-handle handling, and subscription routing follow the
 * normative contract on {@link LibertasEndpointCallback}.
 * @remarks A protocol Response may intentionally omit `@LibertasNextRequest`.
 * Outside workflows, and without WorkflowRequest, it is a non-transition acknowledgement, commonly a
 * shared Success or Failure: clients consume it without replacing their
 * displayed protocol data or next-request choices. The interaction's reference
 * context follows the shared protocol reference context rule.
 * Omission never exposes every Request. A SubscriptionData/DataReport sent
 * through {@link libertasEndpointReport} still refreshes subscribed state,
 * including when the schema variant also has the Response role.
 */
declare function libertasEndpointSendResponse<T>(device: LibertasEndpoint, action: EndpointAction, message: T, dest: LibertasPeer, transId: LibertasTransId): void;

/**
 * Publishes endpoint subscription data.
 *
 * @param device The serving endpoint.
 * @param message The report payload.
 * @param peer Optional opaque peer handle, previously learned from an endpoint
 * callback, for genuinely peer-specific data. Pass it back unchanged. Omit it
 * for normal common reports; the host performs fan-out through active pairs in
 * its current process-memory subscription map.
 * @remarks Reports represent application data and are decoded, cached, and
 * delivered to data consumers. Use {@link libertasEndpointPeerAlive} when the
 * server needs to refresh client watchdogs without publishing changed data.
 * Broadcast and targeted authorization follow the normative contract on
 * {@link LibertasEndpointCallback}.
 */
declare function libertasEndpointReport<T>(device: LibertasEndpoint, message: T, peer?: LibertasPeer): void;

/**
 * Publishes a standardized endpoint liveness signal without protocol data.
 *
 * @param device The serving endpoint.
 * @param peer Optional opaque peer handle, previously learned from an endpoint
 * callback, for a targeted signal. Pass it back unchanged and never interpret
 * it as an App, task, or object identity. Omit it for host fan-out through the
 * endpoint's active pairs in the current process-memory subscription map.
 * @remarks Encoding, authorization, fan-out, watchdog behavior, lifecycle
 * fencing, and prohibited data/UI effects are defined by the normative
 * contract on {@link LibertasEndpointCallback}.
 */
declare function libertasEndpointPeerAlive(device: LibertasEndpoint, peer?: LibertasPeer): void;

/**
 * Endpoint message callback.
 * @param device A {@link LibertasEndpoint}.
 * @param func Callback function.
 * @param tag Developer defined data that will be passed to callback function.
 * @remarks The callback and all endpoint subscription/signaling APIs obey the
 * normative contract documented on {@link LibertasEndpointCallback}.
 */
declare function libertasSetOnEndpoint<T>(device: LibertasEndpoint, func: LibertasEndpointCallback<T>, tag?: any): void;

/**
 * The signature of timer callback function.
 *
 * @param timer A timer returned from {@link libertasTimerNewInterval} or {@link libertasTimerNewDeadline}.
 * @param now Current time in microseconds on the timer's clock: monotonic ticks
 * for interval timers, or UTC microseconds since the Unix epoch for deadline
 * timers. The monotonic clock's origin has no calendar meaning.
 * @param tag A context object passed when creating the timer.
 *
 * @remarks The host event loop automatically dispatches due timer callbacks.
 * Integer microsecond ticks remain exact through Number.MAX_SAFE_INTEGER.
 *
 * @see {@link libertasTimerNewInterval}
 * @see {@link libertasTimerNewDeadline}
 * @see {@link libertasTimerUpdate}
 */
declare type LibertasTimerCallback = (timer: LibertasTimer, now: number, tag: any) => void;

/**
 * Create a new interval timer.
 *
 * @param timeout Positive target time in monotonic microsecond ticks. If the
 * timeout is 0, the timer is put on hold; use {@link libertasTimerUpdate} later
 * to schedule it. Clock domains are defined on {@link LibertasTimerCallback}.
 * @param func Callback function.
 * @param tag Developer-defined tag value to be passed over to the callback function.
 *
 * @returns A new timer object.
 *
 * @remarks
 * Timer is always a one-off. The host cancels its scheduled occurrence before
 * invoking the callback, which may reschedule it with {@link libertasTimerUpdate}.
 *
 * Both active timers and canceled timers can be reused by calling {@link libertasTimerUpdate}. Always try to
 * reuse instead of creating new timers.
 *
 * Callback dispatch follows {@link LibertasTimerCallback}.
 *
 * @see {@link libertasTimerCancel}
 * @see {@link libertasTimerUpdate}
 */
declare function libertasTimerNewInterval(timeout: number, func: LibertasTimerCallback, tag?: any): LibertasTimer;

/**
 * Create a new deadline timer.
 *
 * @param timeout Positive target time in UTC microseconds since the Unix epoch.
 * If the timeout is 0, the timer is put on hold; use {@link libertasTimerUpdate}
 * later to schedule it.
 * @param func Callback function.
 * @param tag Developer-defined tag value to be passed over to the callback function.
 *
 * @returns A new timer object.
 *
 * @remarks
 * Timer is always a one-off. The host cancels its scheduled occurrence before
 * invoking the callback, which may reschedule it with {@link libertasTimerUpdate}.
 *
 * Both active timers and canceled timers can be reused by calling {@link libertasTimerUpdate}. Always try to
 * reuse instead of creating new timers.
 *
 * Callback dispatch follows {@link LibertasTimerCallback}.
 *
 * @see {@link libertasTimerCancel}
 * @see {@link libertasTimerUpdate}
 */
declare function libertasTimerNewDeadline(timeout: number, func: LibertasTimerCallback, tag?: any): LibertasTimer;

/**
 * Cancels a timer so it won't be triggered.
 *
 * @param timer A {@link LibertasTimer} created with {@link libertasTimerNewInterval} or {@link libertasTimerNewDeadline}.
 *
 * @remarks
 * Timer is always a one-off. The host cancels its scheduled occurrence before
 * invoking the callback, which may reschedule it with {@link libertasTimerUpdate}.
 *
 * Both active timers and canceled timers can be reused by calling {@link libertasTimerUpdate}. Always try to
 * reuse instead of creating new timers. Use {@link libertasTimerDestroy} to completely destroy a timer.
 *
 * Callback dispatch follows {@link LibertasTimerCallback}.
 *
 * @see {@link libertasTimerNewInterval}
 * @see {@link libertasTimerNewDeadline}
 * @see {@link libertasTimerUpdate}
 */
declare function libertasTimerCancel(timer: LibertasTimer): void;

/**
 * Destroy a timer and releases all related resources.
 * @param timer A {@link LibertasTimer} created with {@link libertasTimerNewInterval} or {@link libertasTimerNewDeadline}.
 *
 * The timer cannot be used after this call.
 */
declare function libertasTimerDestroy(timer: LibertasTimer): void;

/**
 * Reset and update a timer.
 *
 * @param timer A {@link LibertasTimer} created with {@link libertasTimerNewInterval} or {@link libertasTimerNewDeadline}.
 * @param timeout Positive target time in microseconds on the timer's original
 * clock: monotonic ticks for an interval timer, or UTC microseconds since the
 * Unix epoch for a deadline timer. Zero puts the timer on hold.
 * @param func Optional. If present, replace the callback function of an old-timer.
 * @param tag Optional. If present, replace the tag object of an old-timer.
 *
 * @see {@link libertasTimerNewInterval}
 * @see {@link libertasTimerNewDeadline}
 * @see {@link LibertasTimerCallback}
 * @see {@link libertasTimerCancel}
 *
 * @remarks Arguments func and tag will not be reset to undefined or null. If arguments are undefined, original values will be kept.
 *
 * Timer is always a one-off. The host cancels its scheduled occurrence before
 * invoking the callback, which may reschedule it with {@link libertasTimerUpdate}.
 *
 * Both active timers and canceled timers can be reused by calling {@link libertasTimerUpdate}. Always try to
 * reuse instead of creating new timers.
 *
 * Callback dispatch follows {@link LibertasTimerCallback}.
 */
declare function libertasTimerUpdate(timer: LibertasTimer, timeout: number, func?: LibertasTimerCallback, tag?: any): void

/**
 * Notification severity levels.
 *
 * - `Debug`: Debugging info.
 * - `Info`: General info.
 * - `AlertLow`: Low-priority alerts.
 * - `AlertGuarded`: Guarded alerts.
 * - `AlertElevated`: Elevated alerts.
 * - `AlertHigh`: High alerts.
 * - `AlertSevere`: Severe alerts.
 */
declare type NotificationImportance = number;

/**
 * Arguments for notification templates.
 *
 * Supports various data types for message formatting.
 *
 * The rendering of the message follows Libertas Message Format 1 (LMF1),
 * based on ICU MessageFormat 1 with zero-based positional arguments and
 * Libertas semantic types. This type supports
 * literal text, resource text, objects, boolean values, numerical values, and
 * unit values with specific unit types.
 *
 * These arguments allow messages to be rich in content and convey a wide range
 * of information to users or other parts of the system when sending
 * notifications through the Libertas system.
 *
 * This type is also used in `DataName` tuples to give single records and
 * indexed databases/tables predictable identities whose package-local LMF1
 * templates let clients render localized human names.
 */
declare type LibertasMessageArgument =
    |
    /**
     * Discriminant `type: 0` — literal text.
     * A literal string argument included in the message as-is, without being
     * treated as a resource string. This can be used to include specific text that
     * does not need to be localized or looked up from resources.
     */
    { type: 0; value: string }
    |
    /**
     * Discriminant `type: 1` — Libertas system object.
     * A Libertas system object, such as a device, user, or other entity within the
     * system. The value is expected to be a 32-bit unsigned integer identifier.
     *
     * The application task must have access permission to the object in order to
     * include it as an argument in the message.
     */
    { type: 1; value: LibertasId }
    |
    /**
     * Discriminant `type: 2` — Boolean.
     * A boolean value, true or false, included as an argument in a message.
     */
    { type: 2; value: boolean }
    |
    /**
     * Discriminant `type: 3` — signed integer.
     * A signed integer value included as an argument in a message.
     *
     * This can convey counts, measurements, or other integer-based data that can
     * be positive or negative.
     */
    { type: 3; value: bigint }
    |
    /**
     * Discriminant `type: 4` — unsigned integer.
     * An unsigned integer value included as an argument in a message.
     *
     * This can convey non-negative numerical information such as counts, sizes, or
     * other unsigned integer-based data.
     */
    { type: 4; value: bigint }
    |
    /**
     * Discriminant `type: 5` — single-precision number.
     * A single-precision floating-point value included as an argument in a
     * message.
     */
    { type: 5; value: number }
    |
    /**
     * Discriminant `type: 6` — double-precision number.
     * A double-precision floating-point value included as an argument in a
     * message.
     */
    { type: 6; value: number }
    |
    /**
     * Discriminant `type: 7` — signed integer with a unit type.
     * A signed integer value with a specific unit type.
     *
     * This can represent measurements or other data with a unit of measurement,
     * such as temperature, distance, or another relevant unit.
     */
    { type: 7; unit_type: string; value: bigint }
    |
    /**
     * Discriminant `type: 8` — unsigned integer with a unit type.
     * An unsigned integer value with a specific unit type.
     *
     * This can represent measurements or other non-negative data with a unit of
     * measurement, such as file sizes, speeds, or another relevant unit.
     */
    { type: 8; unit_type: string; value: bigint }
    |
    /**
     * Discriminant `type: 9` — single-precision number with a unit type.
     * A single-precision floating-point value with a specific unit type.
     */
    { type: 9; unit_type: string; value: number }
    |
    /**
     * Discriminant `type: 10` — double-precision number with a unit type.
     * A double-precision floating-point value with a specific unit type.
     */
    { type: 10; unit_type: string; value: number }
    |
    /**
     * Discriminant `type: 11` — resource text.
     * A resource string argument.
     *
     * This is included in the message as a reference to a resource string rather
     * than as literal text. This allows the text to be localized or looked up from
     * resources based on the user's language or other context.
     */
    { type: 11; value: string }
    |
    /**
     * Discriminant `type: 12` — plural selector value.
     * A plural value used for pluralization.
     *
     * This is typically used with resource string templates that have plural
     * forms. The value determines which plural form of the resource string should
     * be used when generating the final message.
     */
    { type: 12; value: bigint };

/**
 * Encodes a FormattedText value as its canonical byte tuple.
 *
 * The returned `Uint8Array` contains the resource name and ordered typed
 * Libertas Message Arguments. Use it directly for a Bytes field marked with
 * `@LibertasFormattedText` and statically protected by `@LibertasReadOnly`;
 * do not Base64-wrap it in App code. This function encodes the value but does
 * not render or decode LMF1.
 *
 * @param resourceName - Key of the localized LMF1 resource template.
 * @param arguments_ - Zero-based ordered arguments referenced by the template.
 * @returns Canonical FormattedText bytes.
 */
declare function libertasFormattedText(
  resourceName: string,
  arguments_: readonly LibertasMessageArgument[],
): Uint8Array;

/**
 * Sends a templated notification to recipients.
 *
 * @param recipients - List of recipient IDs.
 * @param level - Message severity.
 * @param resource_name - Template resource name.
 * @param args - Template arguments.
 * @param source - Optional source ID. If omitted, the current task ID is used.
 *
 * @throws On size limits or permission violations.
 */
declare function libertasNotificationSend(recipients: LibertasUser[], level: NotificationImportance, resource_name: string, args: LibertasMessageArgument[], source?: LibertasId): void;

/**
 * Sends a literal text notification.
 *
 * @param recipients - List of recipient IDs.
 * @param level - Message severity.
 * @param text - Message content.
 * @param source - Optional source ID. If omitted, the current task ID is used.
 *
 * @throws On size limits or permission violations.
 */
declare function libertasNotificationSendLiteral(recipients: LibertasUser[], level: NotificationImportance, text: string, source?: LibertasId): void;

/**
 * Decoded view of a canonical Libertas data name.
 *
 * On the storage boundary, the resource key and ordered, typed Libertas
 * Message Arguments are encoded as one canonical byte blob. That blob is the
 * sole identity of a single record or indexed database/table; it is not a
 * literal or rendered String name. The same tuple is also a FormattedText
 * value: the current task's package selects the `StringResources` catalog,
 * `resourceName` selects an LMF1 template, and `arguments` supply its data so a
 * client can render a localized human name.
 *
 * SDK data operations accept the decoded tuple and perform the canonical byte
 * encoding. App code must not pre-render, Base64-wrap, or separately encode a
 * data name. A translation or template-wording change leaves identity intact;
 * changing the resource key, argument order, argument type, or argument value
 * creates a different identity.
 *
 * Single-record and indexed-database names occupy separate namespaces even
 * when their canonical bytes match. An indexed row's signed index is
 * additional identity and is not part of this tuple.
 */
declare interface DataName {
    /** Package-local key of the LMF1 template in `StringResources`. */
    resourceName: string;

    /** Ordered, typed values used for both byte identity and human rendering. */
    arguments: LibertasMessageArgument[];
}

declare type IndexDirection = number;

/**
 * Statistics for opened indexed data.
 *
 * Contains handle, record count, and index range.
 *
 * If `count` is `0`, callers must ignore `minIndex` and `maxIndex`; their values
 * are unspecified. Otherwise, record indices are in `[minIndex, maxIndex]`.
 */
declare interface IndexedDataStat {
  /** Database handle. */
  handle: LibertasDataStore;

  /** Number of records in the indexed data store. */
  count: bigint;

  /** Minimum record index. Use only when `count` is nonzero. */
  minIndex: bigint;

  /** Maximum record index. Use only when `count` is nonzero. */
  maxIndex: bigint;
}

/**
 * Indexed data record with index and decoded data.
 */
declare interface IndexedData<T> {
  /** Record index. */
  index: bigint;

  /** Decoded record data. */
  data: T;
}

/**
 * Returns all single-record data names.
 *
 * @returns Data names with resource names and arguments.
 */
declare function libertasDataGetSingleNames(): DataName[];

/**
 * Returns all indexed data names.
 *
 * @returns Indexed data names.
 */
declare function libertasDataGetIndexedNames(): DataName[];

/**
 * Removes a single record by resource name and arguments.
 *
 * @param resourceName - Package-local LMF1 resource key in `StringResources`.
 * @param arguments_ - Ordered, typed values identifying and naming the record.
 */
declare function libertasDataRemoveSingle(
  resourceName: string,
  arguments_: readonly LibertasMessageArgument[],
): void;

/**
 * Removes a piece of indexed data from the indexed database.
 *
 * The SDK canonically encodes the resource key and arguments into the byte blob
 * that identifies and localizes the indexed database. After this function is
 * called, the specified indexed data will no longer be available.
 *
 * Unlike a single record, indexed data is organized by an index value for
 * ordered lookup.
 *
 * When you remove indexed data using this function, you are removing all
 * records that match the specified resource name and arguments, regardless of
 * their index values.
 *
 * @param resourceName - Package-local LMF1 resource key in `StringResources`.
 * @param arguments_ - Ordered, typed values identifying and naming the indexed
 * database. They must exactly match the tuple used when it was opened.
 */
declare function libertasDataRemoveIndexed(
  resourceName: string,
  arguments_: readonly LibertasMessageArgument[],
): void;

/**
 * Removes indexed records in the given index range.
 *
 * @param db - Database handle. See `libertasDataOpenIndexed` for obtaining the
 * handle.
 * @param indexLo - Lower index bound, inclusive.
 * @param indexHi - Upper index bound, inclusive.
 */
declare function libertasDataRemoveIndexedRecords(
  db: LibertasDataStore,
  indexLo: number | bigint,
  indexHi: number | bigint,
): void;

/**
 * Opens indexed data and returns its handle with stats.
 *
 * @param resourceName - Package-local LMF1 resource key in `StringResources`.
 * @param arguments_ - Ordered, typed values identifying and naming the indexed
 * database.
 *
 * @returns Indexed data stats with handle, count, and index range. If `count`
 * is `0`, callers must ignore `minIndex` and `maxIndex`; their values are unspecified.
 *
 * Failure stops the task in the Hub runtime. Opted-in functions may use
 * libertasDataTryOpenIndexed to receive an error status instead.
 */
declare function libertasDataOpenIndexed(
  resourceName: string,
  arguments_: readonly LibertasMessageArgument[],
): IndexedDataStat;

/**
 * Writes a single record.
 *
 * @param resourceName - Package-local LMF1 resource key in `StringResources`.
 * @param arguments_ - Ordered, typed values identifying and naming the record.
 * @param data - Encodable data.
 */
declare function libertasDataWriteSingle(
  resourceName: string,
  arguments_: readonly LibertasMessageArgument[],
  data: any,
): void;

/**
 * Writes indexed data.
 *
 * @param db - Database handle. See `libertasDataOpenIndexed` for obtaining the
 * handle.
 * @param index - Record index.
 * @param data - Encodable data.
 */
declare function libertasDataWriteIndexed(
  db: LibertasDataStore,
  index: number | bigint,
  data: any,
): void ;

/**
 * Reads a single record.
 *
 * @typeParam T - Decoded data type.
 *
 * @param resourceName - Package-local LMF1 resource key in `StringResources`.
 * @param arguments_ - Ordered, typed values identifying and naming the record.
 *
 * @returns Decoded data, or `undefined` if not found.
 */
declare function libertasDataReadSingle<T> (
  resourceName: string,
  arguments_: readonly LibertasMessageArgument[]
): T | undefined;

/**
 * Reads an indexed data range.
 *
 * @typeParam T - Decoded data type.
 *
 * @param db - Database handle. See `libertasDataOpenIndexed` for obtaining the
 * handle.
 * @param index - Starting index.
 * @param direction - Read direction.
 * @param maxN - Maximum number of records to read.
 *
 * @returns Decoded indexed records.
 */
declare function libertasDataReadIndexedRange<T> (
  db: LibertasDataStore,
  index: bigint,
  direction: IndexDirection,
  maxN: number,
): IndexedData<T>[];

/**
 * Reads a single indexed data record.
 *
 * @typeParam T - Decoded data type.
 *
 * @param db - Database handle. See `libertasDataOpenIndexed` for obtaining the
 * handle.
 * @param index - Record index.
 *
 * @returns Decoded record, or `undefined` if not found.
 */
declare function libertasDataReadIndexed<T>(
  db: LibertasDataStore,
  index: number | bigint,
): T | undefined;

/**
 * Log levels
 */
declare type LogLevel = number;

/**
 * Write a message to system log.
 * @param level Log level.
 * @param message A text message.
 *
 * @remarks The log source is the name of the Libertas App task.
 */
declare function libertasLog(level: LogLevel, message: string): void;

/** Status-returning Data API operations preserve ordinary absence in value. */
declare enum DataStatus {
    Success = 0,
    NotFound = 1,
    InvalidRequest = 2,
    StorageError = 3,
    DataIntegrityError = 4,
    ResourceLimit = 5,
}
type DataResult<T> = { status: DataStatus.Success; value: T } |
    { status: Exclude<DataStatus, DataStatus.Success> };

/** Checked Data API operation; requires @LibertasDataErrorStatus on the task function. */
declare function libertasDataTryGetSingleNames(): DataResult<DataName[]>;

/** Checked Data API operation; requires @LibertasDataErrorStatus on the task function. */
declare function libertasDataTryGetIndexedNames(): DataResult<DataName[]>;

